from pathlib import Path
import sys,json
from after_draw_model import *
OUT=ROOT/'review'
STUDY=Path(sys.argv[1]) if len(sys.argv)>1 else ROOT/'results/study'
study=json.loads((STUDY/'ANALYSIS_R4.json').read_text());samples=json.loads((STUDY/'FIXED_REVIEW_SAMPLES.json').read_text())
# Paired demo: choose the C cell median-powder seed, then use EXACT same seed for A.
demo={}
for p in ('first_box','established_box'):
 seed=samples[f'budget1500|{p}|C']['summary']['seed']
 for c in (candidates()[0],candidates()[2]):
  r,new,proposal=summarize_session(c,seed,p,1500//c.yen_equivalent_per_pull)
  demo[p+'|'+c.id[0]]={'summary':r,'items':[x.as_json() for x in new],'existing':[x.as_json() for x in profile(p)],'proposal':proposal}
blob=json.dumps({'cases':demo,'gear':{k:{'name':v['name'],'slot':v['slot']} for k,v in GEAR.items()},'quality':QUALITIES},ensure_ascii=False,separators=(',',':'))
head='''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>魔導庫｜まとめ引き後の操作検証 R4</title>
<style>
:root{--bg:#101b25;--panel:#182630;--gold:#ceaf70;--fg:#f3ecdf;--muted:#c1c8cb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:15px/1.7 -apple-system,BlinkMacSystemFont,"Hiragino Sans","Yu Gothic",sans-serif}header{padding:20px 18px 16px;border-bottom:1px solid #5c5344;background:linear-gradient(150deg,#243435,#14212c)}h1{font:600 26px/1.5 Georgia,"Hiragino Mincho ProN",serif;margin:4px 0;color:#e8cf99}p{margin:8px 0}.eyebrow{font-size:12px;letter-spacing:1px;color:var(--gold)}main{max-width:510px;margin:auto;padding:18px 16px 80px}label{display:block;margin:8px 0;color:var(--muted);font-size:13px}select{width:100%;min-height:46px;background:#24343d;color:var(--fg);border:1px solid #6a6450;border-radius:5px;padding:8px;font-size:15px}button{min-height:46px;max-width:100%;border:1px solid #998153;border-radius:7px;background:#254744;color:var(--fg);padding:10px 16px;font-size:15px;cursor:pointer;white-space:normal}button:disabled{opacity:.48;cursor:default}.wide{width:100%;margin-top:12px}.secondary{background:#202f39;border-color:#667375}.card{margin:14px 0;padding:15px;background:var(--panel);border:1px solid #526267;border-radius:8px}.row{display:flex;gap:8px;align-items:center;justify-content:space-between}.row>*{min-width:0}.counts{display:grid;grid-template-columns:repeat(5,1fr);gap:5px;margin:14px 0}.count{background:#202f37;border:1px solid #65716b;border-radius:5px;text-align:center;padding:8px 2px}.count b{display:block;font-size:22px}.count small{font-size:11px}.muted{color:var(--muted);font-size:13px}.notice{font-size:13px;padding:12px;border-left:3px solid var(--gold);background:#27302d}h2{font-size:20px;color:#e7d1a4;margin:17px 0 9px}h3{font-size:16px;margin:8px 0}.item{padding:10px 0;border-bottom:1px solid #3e4c51}.item:last-child{border:0}.tag{font-size:12px;color:#ddc995}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:9px}.metrics div{border:1px solid #5d6b63;border-radius:5px;padding:10px;text-align:center}.metrics b{display:block;font-size:22px;color:#e1c68e}.error{color:#ffd5c1;background:#563e35;padding:10px}.success{color:#cbe7c2;background:#233d34;padding:10px}details{margin-top:12px}summary{cursor:pointer;min-height:44px;padding:10px;color:#dac491}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.top{max-width:510px;margin:auto}footer{max-width:510px;padding:15px;margin:auto;color:var(--muted);font-size:12px}a{color:#dfc997}#toast{min-height:24px}.field{margin:10px 0}.step{font-size:13px;letter-spacing:1px;color:#ceaf70}.choice{display:flex;align-items:center;gap:8px;margin:10px 0;font-size:14px;min-height:44px}.choice input{width:22px;height:22px}@media(max-width:360px){main{padding:14px 12px}.count b{font-size:19px}}
</style></head><body><header><div class="top"><div class="eyebrow">魔女の採集帳 / 操作検証 R4</div><h1>魔導庫から、次の強化へ</h1><p class="muted">固定された模擬結果を使います。実課金・抽選・ゲーム保存は行いません。正式なUI A案の改訂ではありません。</p></div></header><main>
<div id="setup"><label for="profile">初期の装備箱</label><select id="profile"><option value="established_box">一通り所有した比較用装備箱</option><option value="first_box">4人の初期武器だけの装備箱</option></select><label for="candidate">比較する案</label><select id="candidate"><option value="C">C コモン入り・1,500円相当50個</option><option value="A">A 希少以上・1,500円相当10個</option></select><button class="wide" id="start">結果を開いて、操作時間を測る</button><p class="muted">ここから読む・考える時間を含めて測れます。記録はこのページ内だけに保持。自動テストの秒数とは別です。</p></div>
<div id="screen" aria-live="polite"></div><div id="toast" role="status"></div></main><footer>所持品と開封結果は先に保護。整理候補は自動消去せず、確認後だけ変換します。希少以上の全件厳選は、この短い導線の完了には含めません。</footer>
<script>const DATA=__DATA__;
'''
js=r'''
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let S=null;
function act(kind){if(S)S.actions.push({kind,t:performance.now()-S.start});}
function qualityLine(counts){return '<div class="counts">'+counts.map((v,i)=>'<div class="count"><small>'+DATA.quality[i]+'</small><b>'+v+'</b></div>').join('')+'</div>';}
function itemRow(i,details=false){return '<div class="item"><div class="row"><span>'+esc(DATA.gear[i.template_id].name)+'</span><span class="tag">'+DATA.quality[i.quality]+'</span></div>'+(i.first_discovery?'<span class="tag">初入手・保護</span>':'')+(i.locked?'<span class="tag"> ロック中</span>':'')+(details?'<p class="muted">'+i.affixes.map(x=>esc(x[0])+'：分位 '+x[1]/100+'%').join('／')+'</p>':'')+'</div>';}
function safeRender(html){$('#screen').innerHTML=html;$('#toast').textContent='';}
function start(){const key=$('#profile').value+'|'+$('#candidate').value;const input=structuredClone(DATA.cases[key]);S={key,input,start:performance.now(),actions:[],selected:false,committed:false,failed:false,failNext:false,revision:0,quoteRevision:null,dust:0,remaining:input.items.slice(),level:0,consumed:0,screen:'result'};$('#setup').hidden=true;renderResult();}
function renderResult(){S.screen='result';const x=S.input.summary, keep=x.retained, offer=x.offered_for_optional_scrap;const high=S.input.items.filter(i=>i.quality>=2).sort((a,b)=>b.quality-a.quality).slice(0,3);
 safeRender('<div class="step">01 開封結果は保存済み</div><h2>'+x.draws+'個の道具を持ち帰りました</h2>'+qualityLine(x.quality_counts)+'<div class="card"><h3>まず見たい道具</h3>'+high.map(i=>itemRow(i)).join('')+'<p class="muted">注目は最大3個。表示されていない個体もすべて残ります。強さの最適化や装備交換は自動では行いません。</p></div><div class="metrics"><div>保留・保護する装備<b>'+keep+'個</b></div><div>整理候補の余剰<b>'+offer+'個</b></div></div>'+(offer?'<button class="wide" data-action="cleanup">低品質の余剰を確認</button>':'<p class="notice">この条件では低品質の整理候補がありません。希少以上は比較用に保留しています。</p>')+'<button class="wide secondary" data-action="forge">工房で強化を確認</button><details><summary>全個体を見る（'+x.draws+'個）</summary>'+S.input.items.map(i=>itemRow(i,true)).join('')+'</details><button class="wide secondary" data-action="finish">今は整理せず、保留して終える</button>');}
function renderCleanup(){S.screen='cleanup';const ids=S.input.proposal.ids, xs=S.input.items.filter(i=>ids.includes(i.uid));const lo=xs.filter(i=>i.quality===0).length, mid=xs.filter(i=>i.quality===1).length;
 safeRender('<div class="step">02 整理候補 / まだ選択していません</div><h2>残すべきものは、分けて保護</h2><p class="notice">ロック・初入手・装備中・保存構成・投資済みは対象外。異なる副効果や、共用装備の必要人数分も残します。</p><div class="card"><div class="row"><span>普通 '+lo+'個 × 1粉</span><b>'+lo+'粉</b></div><div class="row"><span>良質 '+mid+'個 × 2粉</span><b>'+mid*2+'粉</b></div><hr><div class="row"><span>確認後に受け取れる研磨粉</span><b>'+S.input.summary.powder.low+'粉</b></div><p class="muted">1/2粉は今回の検証値。最終還元量ではありません。</p></div><button class="wide" data-action="select">候補をまとめて選ぶ（'+ids.length+'個）</button><button class="wide" data-action="quote" disabled>分解内容を確認</button><details><summary>対象の個体を見る</summary>'+xs.map(i=>itemRow(i,true)).join('')+'</details><button class="wide secondary" data-action="back">戻る・何も消費しない</button>');}
function renderQuote(){S.screen='quote';S.quoteRevision=S.revision;const count=S.input.proposal.ids.length;
 safeRender('<div class="step">03 最終確認</div><h2>'+count+'個を研磨粉へ変換しますか</h2><div class="metrics"><div>残る今回の装備<b>'+S.input.summary.retained+'個</b></div><div>増える研磨粉<b>'+S.input.summary.powder.low+'粉</b></div></div><p class="notice">分解した個体は元に戻せません。これは模擬操作です。実際の購入・ゲーム所持品は変更されません。</p><button class="wide" data-action="commit">'+count+'個を分解する（模擬）</button><button class="wide secondary" data-action="cancel">取り消す</button>');}
function commit(){if(S.committed){renderDone();return;}if(S.quoteRevision!==S.revision){$('#toast').innerHTML='<p class="error">所持状態が変わりました。再確認が必要です。何も消費していません。</p>';return;}
 if(S.failNext){S.failNext=false;S.failed=true;$('#toast').innerHTML='<p class="error">保存失敗の検証。装備も粉も変更していません。再試行できます。</p>';return;}
 const ids=new Set(S.input.proposal.ids);S.remaining=S.remaining.filter(i=>!ids.has(i.uid));S.dust+=S.input.summary.powder.low;S.committed=true;S.revision++;renderDone();}
function renderDone(){S.screen='done';safeRender('<div class="step">04 変換内容を保存済み</div><h2>装備を守って、次の強化へ</h2><div class="metrics"><div>保留している装備<b>'+S.remaining.length+'個</b></div><div>現在の研磨粉<b>'+S.dust+'</b></div></div><p class="success">再度表示しても、粉を二重に付与しません。</p><button class="wide" data-action="forge">工房で強化を確認</button>');}
function renderForge(){S.screen='forge';const need=[5,10,15][S.level]||0,now=14*(1+.03*S.level),next=14*(1+.03*Math.min(3,S.level+1));
 safeRender('<div class="step">05 工房 / 強化費だけの接続試験</div><h2>若枝の採集杖 ＋'+S.level+'</h2><div class="card"><p class="muted">杖単体の威力加算見本。キャラ全体の強さや勝率ではありません。</p><div class="row"><b>'+now.toFixed(2)+' → '+next.toFixed(2)+'</b><span>必要 '+need+'粉</span></div><p>所持：'+S.dust+'粉</p></div><button class="wide" data-action="enhance" '+(S.level>=3||S.dust<need?'disabled':'')+'>杖を＋'+Math.min(3,S.level+1)+'に強化（模擬）</button>'+(S.dust<need?'<p class="muted">この整理分だけでは、次の強化に不足しています。装備の保留や比較はできます。</p>':'')+'<button class="wide secondary" data-action="finish">この手順の計測を終える</button>');}
function finish(){const elapsed=(performance.now()-S.start)/1000;S.screen='finished';S.elapsed=elapsed;const record={case:S.key,seed:S.input.summary.seed,seconds:elapsed,action_count:S.actions.length,actions:S.actions,retained:S.remaining.length,powder_left:S.dust,enhancement:S.level,note:'このページでの操作時間。本人操作か自動試験かは実行者による。品質案の優劣や全件整理時間の証明ではない。'};S.record=record;
 safeRender('<h2>ここまで '+elapsed.toFixed(1)+'秒</h2><p>ボタン操作 '+S.actions.length+'回。残した装備 '+S.remaining.length+'個、杖 ＋'+S.level+'。</p><p class="notice">全ての希少装備を厳選し終えたわけではありません。残した道具は、後から確認する負担として残ります。</p><button class="wide" data-action="restart">もう一方の案・別の状態を試す</button><details><summary>今回の操作記録</summary><pre>'+esc(JSON.stringify(record,null,2))+'</pre></details>');}
$('#start').onclick=start;$('#screen').onclick=e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;act(a);if(a==='cleanup')renderCleanup();else if(a==='select'){S.selected=true;b.textContent='選択済み';$('[data-action="quote"]').disabled=false;}else if(a==='quote'&&S.selected)renderQuote();else if(a==='commit')commit();else if(a==='cancel')renderCleanup();else if(a==='back')renderResult();else if(a==='forge')renderForge();else if(a==='enhance'){const need=[5,10,15][S.level];if(S.level<3&&S.dust>=need){S.dust-=need;S.consumed+=need;S.level++;renderForge();}}else if(a==='finish')finish();else if(a==='restart'){$('#setup').hidden=false;$('#screen').innerHTML='';S=null;}};
window.__qa={state:()=>structuredClone(S), failNext:()=>{S.failNext=true;}, stale:()=>{S.revision++;}, duplicate:()=>commit(), data:DATA};
</script></body></html>
'''
OUT.mkdir(exist_ok=True,parents=True);(OUT/'AFTER_DRAW_REVIEW.html').write_text(head.replace('__DATA__',blob)+js)
(OUT/'DEMO_INPUT.json').write_text(json.dumps({'cases':demo},ensure_ascii=False,indent=2)+'\n')
print('demo chars',len(head)+len(blob)+len(js))
